// Test-only validated Macro transform probe retained/extended from independent rereview.
use editor_core::*;use editor_core::edit::SelectionGroup;use editor_core::hit_test::selection_geometry::{calculate,CompositeMaterial};use std::io::{self,BufRead};
fn main(){for line in io::stdin().lock().lines(){let line=line.unwrap();let v:Vec<f64>=line.split_whitespace().map(|s|s.parse().unwrap()).collect();let [r,s,dx,dy,scale,worldx,worldy,rotation]=v[..8] else{panic!()};let mirror=match v.get(8).copied().unwrap_or(0.) as usize {0=>Mirror::None,1=>Mirror::X,2=>Mirror::Y,3=>Mirror::Xy,_=>panic!()};let lx=v.get(9).copied().unwrap_or(0.);let ly=v.get(10).copied().unwrap_or(0.);let mut d=SemanticDocument{id:"d".into(),unit:"mm".into(),format:SemanticFormat{integer:4,decimal:6,leading_zero_omission:true,absolute:true},layers:vec![SemanticLayer{id:"l".into(),objects:vec![]}],apertures:vec![ApertureDefinition{id:"a".into(),source_dcode:10,shape:ApertureShape::Macro{primitives:vec![MacroPrimitive::Circle{exposure:Exposure::Dark,diameter_mm:2.*r,center:MmPoint::new(lx,ly),rotation_deg:0.},MacroPrimitive::Circle{exposure:Exposure::Dark,diameter_mm:2.*s,center:MmPoint::new(lx+dx,ly+dy),rotation_deg:0.}]}}],source:SourceMetadata::default(),block_definitions:vec![]};d.layers[0].objects.push(SemanticObject{object_id:"o".into(),geometry:SemanticGeometry::Flash{center:MmPoint::new(worldx,worldy),aperture_id:"a".into(),transform:LocalTransform{scale,rotation_deg:rotation,mirror}},exposure:Exposure::Dark,origin:ObjectOrigin::Imported{command_index:0}});d.validate().unwrap();let before=d.clone();let groups=vec![SelectionGroup{layer_id:"l".into(),object_ids:vec!["o".into()]}];match calculate(&d,&groups,1e-4,||false){Ok(q)=>match q.material{CompositeMaterial::Ready{area_mm2,perimeter_mm,centroid_mm,centroid_error_mm,area_error_mm2,perimeter_error_mm,..}=>println!("READY {area_mm2:.17e} {perimeter_mm:.17e} {:.17e} {:.17e} {centroid_error_mm:.17e} {area_error_mm2:.17e} {perimeter_error_mm:.17e}",centroid_mm.x_mm,centroid_mm.y_mm),CompositeMaterial::ZeroArea=>println!("ZERO")},Err(e)=>println!("ERR {e:?}")};assert_eq!(d,before);}}
